  AwakerTalent_122607_TalentDesc_1 = {
    Text = "·Setelah memainkan 2 kartu \"Pukulan\", \"Moxia\" akan melakukan serangan balasan, menyebabkan kerusakan sebanyak 1 kali sebesar 30% dari daya serang \"Moxia\" dan dianggap sebagai \"Pukulan\", maksimal berlaku 4 kali per putaran."
  },
  AwakerTalent_122607_TalentName_1 = {
