  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "·Talent ini hanya berlaku di level \"Bab Bintang\".\n·CON, ATK, dan Pertahanan Awakener ini meningkat sebesar [Arg1]%, dan setelah Awakener ini pertama kali play Rouse, dapatkan [Arg2] poin Keyflare.\n·Efek Racun yang dipicu oleh semua Awakener meningkat sebesar [Arg3]%.\n·Setiap lapisan \"Mabuk\" mengurangi kerusakan yang diberikan oleh musuh \"Humanoid\" sebesar 1%, dan saat dihapus, memberikan Kerusakan Murni sebesar 1% Max HP kepada musuh \"Humanoid\"."
  },
