  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·Saat Arachne ada dalam tim, akan mengganti Realm \"Ultra\" dengan Realm \"Singularity: Ultra\".\n·Penjelajahan Dimensi: Efek ini dipicu setelah pertama kali play Kartu perintah setiap ronde, menempatkan salinan asli sementaranya ke Ruang Ultra dan memberikan 25 stacks \"Prisma Singularitas\" padanya dan salinan sementara tersebut, efek ini tidak dapat diaktifkan pada Ultra Round.\n·Prisma Singularitas: Setiap 1 stack yang dimiliki meningkatkan kerusakan, STR tetap dan peningkatan Kerusakan tentakel, efek akhir Racun tetap, Counter tetap yang disebabkan kartu ini sebesar 2%, efek akhir Perisai tetap, pemulihan HP tetap, STR▼ meningkat 1%, dihapus setelah di-play. Kartu yang memiliki Prisma Singularitas tidak dapat memicu \"Penjelajahan Dimensi\".\n·Ruang Ultra: Saat Ruang Ultra mencapai batas, akhir ronde diganti dengan mengaktifkan Ruang Ultra: tidak lagi mendapatkan ronde tambahan, buang Hand yang tidak di-Retain dan picu efek Void, masukkan semua kartu di Ruang Ultra ke tangan, atur Arithmetica saat ini menjadi 5 poin. Setelah mengaktifkan Ruang Ultra, ronde ini dianggap sebagai Ultra Round.\n·\"Pembantaian Singularity\": Ambil kartu paling kiri di Ruang Ultra. Cooldown 3 ronde.\n·Setelah eksplorasi dimulai, DMG Amplification tim +50%, dan dapatkan 15 stacks \"Prisma Singularitas\".\n·\"Prisma Singularitas\": Semua Kartu perintah dianggap memiliki bonus Prisma Singularitas dalam jumlah yang sama.\n·Ultra Mastery: Setiap 1 poin Realm Mastery yang dimiliki tim, meningkatkan jumlah stacks \"Prisma Singularitas\" yang diberikan oleh \"Prisma Singularitas\" dan \"Penjelajahan Dimensi\" sebesar 0,05％.\n·Ultra Murni: Jika tim hanya terdiri dari Awakener Ultra atau Chaos, efek Ultra Mastery dan DMG Amplification yang diberikan Realm berlipat ganda."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Benang Takdir"
  },
