  AwakerTalent_130398_TalentDesc_1 = {
    Text = "·Bakat ini hanya berlaku di Tingkat \"Bab Bintang\".\n·Konstitusi, Serangan, dan Pertahanan Awakener ini meningkat sebesar [Arg1]%, dan membuat Awakener ini mendapatkan [Arg2] poin Keyflare setelah pertama kali memainkan Rouse.\n·Awakener yang dipilih oleh \"Senandung Saya\" mendapatkan [Arg3] tumpukan \"Festival Pembiakan\", dan membuat Posse berikutnya berlaku 2 kali.\n·\"Corrosion\" yang diberikan Saya kepada musuh \"Caro\" meningkat tambahan sebesar [Arg4]%."
  },
