    Text = "·Talent ini hanya berlaku di level \"Bab Bintang\".\n·CON, ATK, dan Pertahanan Awakener ini meningkat sebesar [Arg1]%, dan setelah pertama kali play Rouse, Awakener ini mendapatkan [Arg2] poin Keyflare.\n·Efek STR▼ yang diberikan \"Bayangan Tak Bertepi\" dan pengganda kekuatan yang diperoleh meningkat [Arg3]%, setiap kali berlaku membuat \"Ujung Senapan Berdosa\" berikutnya mendapatkan bonus kekuatan tambahan sebesar [Arg4]%, batas maksimum 1200%."
