  AwakerTalent_141303_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di Tingkat \"Bab Bintang\".\n· CON, Serangan, dan Pertahanan Awakener ini meningkat sebesar [Arg1] %, dan setelah Awakener ini pertama kali play Rouse, ia akan memperoleh [Arg2] poin Keyflare.\n· Fixed DMG yang diberikan \"Pontos\" kepada musuh \"Kaum Yang Dimuliakan\" meningkat sebesar [Arg3]%.\n· \"Perburuan Tanpa Akhir\" setiap menghabiskan 10 poin Aliemus mendapatkan Kerusakan tentakel sebesar [Arg4]% ATK, \"Amukan Gaunt\" saat menyebabkan kerusakan juga akan sementara menurunkan Kekuatan DEF target sebesar [Arg5]%."
  },
