  AwakerTalent_143615_TalentDesc_1 = {
    Text = "·Saat Karakter ini berada dalam tim, Realm \"Aequor\" akan digantikan oleh Realm \"Benthos: Aequor\".\n·Kerusakan tentakel dasar diubah menjadi 5% dari Max HP tim.\n·Setelah eksplorasi dimulai, DMG Amplification tim +50%, jika tim hanya terdiri dari Awakener Aequor atau Chaos, DMG Amplification yang diperoleh dari efek ini berlipat ganda, namun saat pertempuran dimulai tidak lagi mendapatkan Tentacle tambahan.\n·Tidak lagi memiliki efek \"Pertemuan Tentakel\".\n·Postur Tentakel diubah menjadi \"Benthos: Postur Tentakel\".\n·\"Benthos: Lautan Tenang\": Mendapatkan Perisai sebesar 25% Max HP, setelah giliran berakhir Tentacle tidak lagi menyerang, cooldown 3 giliran.\n·\"Benthos: Ombak Bergelora\": Membuat Kerusakan tentakel pada giliran ini menjadi 125%, setelah menimbulkan Active DMG membuat 1 Tentacle menyerang, namun setelah giliran berakhir kehilangan 1 Tentacle, cooldown 3 giliran.\n·Realm Mastery diubah menjadi \"Benthos: Kuasai Aequor\", setiap poin Realm Mastery meningkatkan Perisai \"Benthos: Lautan Tenang\" sebesar 0.025% Max HP, dan meningkatkan Kerusakan tentakel \"Benthos: Ombak Bergelora\" sebesar tambahan 0.025%.\n·Jika tim hanya terdiri dari Awakener Aequor atau Chaos, efek \"Benthos: Realm Mastery\" berlipat ganda."
  },
