  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Talent ini hanya berlaku di Tingkat \"Bab Bintang\".\n·CON, Serangan, dan Pertahanan Awakener ini meningkat [Arg1]%, dan membuat Awakener ini mendapatkan [Arg2] poin Keyflare setelah pertama kali men-play Rouse.\n·\"Pembelah Dunia\" mendapatkan bonus Strength tambahan sebesar [Arg3]%, setelah Bunuh musuh mendapatkan [Arg4] Segil hitam, menikmati bonus Black Sigil Yield milik sendiri, maksimal berlaku 1 kali per pertempuran."
  },
