  AwakerTalent_145718_TalentDesc_1 = {
    Text = "·Saat Caraboo ada dalam tim, akan mengganti Realm \"Caro\" dengan Realm \"Propagation: Caro\".\n·Embryo Fusion: Embryo Fusion yang diperoleh setiap giliran ditingkatkan menjadi 50~100, meningkat seiring HP yang hilang, namun batas Embryo Fusion ditingkatkan dari 100 menjadi 200, saat mencapai batas akan menempatkan \"繁育·胚胎\" ke tangan.\n·Mengembangbiakkan embrio: Saat di-play tidak lagi mendapatkan Crit. Rate, Devour juga tidak lagi mendapatkan Perisai dan Temporary STR. Saat setiap Awakener pertama kali mengonsumsi \"繁育·胚胎\" setiap giliran, dapatkan 40 tumpukan \"Festival Pembiakan\": Setiap memiliki 1 tumpukan, efek akhir dari Kerusakan Exalt berikutnya giliran ini, Perisai tetap, pemulihan HP tetap, Strength tetap, STR▼, peningkatan Kerusakan tentakel, Racun tetap, Counter tetap dari Awakener tersebut meningkat 1%.\n·Crimson Furnace: Jumlah akumulasi otomatis di awal giliran diubah menjadi 10% HP yang hilang, jumlah akumulasi maksimum diubah menjadi 50% Max HP. Tidak lagi berakumulasi saat pertempuran berakhir, memiliki cooldown 3 giliran saat digunakan.\n·Erosi Merah: Setelah menggunakan Crimson Furnace, memberikan Corrosion sebesar 1% Max HP target kepada semua musuh, semakin banyak Crimson Furnace yang dikonsumsi semakin kuat efek Corrosion-nya, maksimal meningkat 100%. Memberikan efek Corrosion 5 kali lipat kepada musuh \"Cangkang kosong\".\n·Setelah eksplorasi dimulai, Max HP meningkat 10%, DMG Amplification tim +50%, setiap awal giliran semua Awakener mendapatkan 20 tumpukan \"Festival Pembiakan\". Jika tim hanya terdiri dari Awakener Caro atau Chaos, DMG Amplification yang diperoleh dari efek ini berlipat ganda.\n·Realm Mastery berubah menjadi \"Penguasaan Caro Pembiakan\", setiap poin Realm Mastery meningkatkan \"Festival Pembiakan\" yang diperoleh dari \"Propagation: Caro\" sebesar 0,05%.\n·Jika tim hanya terdiri dari Awakener Caro atau Chaos, efek \"Penguasaan Caro Pembiakan\" berlipat ganda."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Tanah Suci Pembiakan"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·Saat Lotan: Cetarchon ada dalam tim, ganti Realm \"Chaos\" dengan Realm \"Primordia: Chaos\".\n·Arus Arkais: Keyflare dasar ditingkatkan menjadi 2000 poin, DMG Amplification tim +50%, serangan dan pertahanan semua Awakener meningkat 10%. Jika tim hanya terdiri dari Kebangkitan kekacauan, DMG Amplification yang diperoleh dari efek ini berlipat ganda. Saat pertempuran dimulai, dapatkan 2000 poin Keyflare.\n·Kunci Penyatuan: Tingkat Muatan Kunci Perak semua Awakener berubah menjadi rata-rata tim. Dan tidak lagi mendapatkan Keyflare berdasarkan Arithmetica Cost, melainkan setiap Awakener mendapatkan Keyflare sebesar \"Keyflare Regen Awakener tersebut ×3+100\" dari Kartu perintah pertama setiap ronde.\n·Alam Tak Terpisahkan: Tidak lagi memicu Ultra Murni Realm lain, efek penggandaan Mastery, dan efek penggandaan Amplification.\n·Gema Arkais: Rouse mendapatkan Prepare 1, saat pertama kali di-play setiap ronde, Posse yang dibawa akan otomatis dilepaskan.\n·Pecahan Memori: Posse digantikan oleh \"Primordia: Kejadian Berulang\" dan \"Primordia: Wahyu Trinitas\", Posse yang dibawa sendiri tidak dapat dilepaskan.\n·Primordia · Kejadian Berulang: Temukan 3 jenis Posse dari Posse yang dimiliki, pilih 1 Posse untuk membuatnya berlaku 2 kali.\n·Primordia · Wahyu Trinitas: Temukan 3 kelompok Posse dari Posse yang dimiliki, setiap kelompok terdiri dari 3 jenis Posse yang berbeda, pilih satu kelompok untuk membuat Posse di dalamnya berlaku masing-masing 1 kali secara berurutan.\n·Posse dalam Primordia: Kejadian Berulang dan Primordia: Wahyu Trinitas akan mencakup delapan jenis \"Memori Arkais\".\n·Primordia: Kejadian Berulang dan Primordia: Wahyu Trinitas hanya dianggap melepaskan Posse 1 kali, saat berlaku beberapa kali hanya berlaku untuk Posse pertama yang berlaku.\n·Realm Mastery berubah menjadi \"Penguasaan Primordia: Chaos\", setiap poin Realm Mastery meningkatkan intensitas Posse sebesar 0,05%.\n·Setiap poin intensitas Posse meningkatkan Racun tetap, Counter tetap, STR tetap, Kerusakan tentakel tetap, Abu sisa lama tetap yang disebabkan Posse sebesar 2%, meningkatkan Perisai tetap, pemulihan HP tetap, STR▼, Crit. Rate, Crit. DMG, DMG Amplification, Realm Mastery, Aliemus, Embryo Fusion, Keyflare sebesar 1%.\n·Jika tim hanya terdiri dari Kebangkitan kekacauan, efek \"Penguasaan Primordia: Chaos\" berlipat ganda."
  },
  AwakerTalent_146937_TalentName_1 = {Text = "Atma Kuno"},
