  AwakerTalent_44845_TalentDesc_1 = {
    Text = "· Setiap 1% ketahanan terhadap kematian yang disediakan oleh bangunan Lily sendiri, roda takdir, dan perjanjian, meningkatkan perlindungan dasar \"Rawa Terlarang\" dan \"Pertahanan Dasar\" sebesar 0.25%, dan dalam pertempuran bos, penumpukan dan batasan Bertahan meningkat 0.25%.\n· Saat Lily berada dalam tim, setiap kehilangan 1 poin hidup mendapatkan 1 lapisan Bertahan, batas penumpukan Bertahan sama dengan kesehatan maksimum."
  },
