  AwakerTalent_46445_TalentDesc_1 = {
    Text = "· Efek pemulihan yang disediakan oleh Salvador dari tungku akan mendapatkan peningkatan dari peningkatan pemulihan hidup."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Penjaga jiwa"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "· Ramona mendapatkan tambahan 2.5 poin properti isi ulang kunci perak. Setiap tingkat affiniti tambahan memberikan Ramona 0.5 poin properti isi ulang kunci perak.\n· Setiap 1 poin tingkat isi ulang kunci perak yang dimiliki Ramona meningkatkan kerusakan dasar \"Pedang Ratu\" sebesar 1%, dan setelah digunakan mendapatkan 0.75 penguasaan Alam sementara."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Resonansi Hati dan Perak"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "· Ramona-loop mendapatkan tambahan 2.5 poin properti isi ulang kunci perak. Setiap tingkat affiniti tambahan memberikan Ramona-loop 0.5 poin properti isi ulang kunci perak.\n· Setiap 1 poin tingkat isi ulang kunci perak yang dimiliki meningkatkan efek siklus \"Pukulan Dasar\" sebesar 0.2%, dan efek siklus \"Pertahanan Dasar\" memberikan 0.2 Aliemus."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Resonansi Hati dan Perak"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "· Untuk setiap 1 poin penguasaan alam yang dimiliki Nautila, serangan “Siap dan Set” meningkatkan counter sebesar 0.25%."
  },
  AwakerTalent_49872_TalentName_1 = {Text = "perawatan"},
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "· Setiap 1% properti kekuatan kerusakan yang dimiliki oleh Nymphaea meningkatkan efek dasar racun yang ditimbulkan oleh \"Lonceng Kematian\" dan \"Pemakaman Sendiri\" sebesar 0.5%."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Impregnation"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·Pada awal pertempuran, tempatkan 1 kartu \"Kegilaan\" ke dalam tangan. \n ·\"Pukulan dasar\" Miryam mendapatkan bonus 100% Kerusakan tentakel. \n ·Setiap kali Awakener, Roda takdir, dan Covenant memberikan 1% kerusakan kritikal, kekuatan Exalt, Kerusakan tentakel, Aliemus, serta efek Racun yang diterapkan dan dipicu meningkat 0.2%."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Kesetiaan Tidak Lekas Padam"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "· Tulu, Roda takdir yang dipasang, dan Perjanjian memberikan 1 tingkat Aliemus isi ulang setiap 1 poin, \"Serangan dasar\" akan mendapatkan 5% Tentakel kerusakan dan Kekuatan, \"Perintah jurang\" mendapatkan 15% Tentakel kerusakan dan Kekuatan."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Kekuasaan Dewa Raja"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "· Setiap 1% ketahanan terhadap kematian yang disediakan oleh bangunan Sanga sendiri, roda takdir, dan perjanjian, meningkatkan Aliemus yang diterima oleh \"Pukulan Dasar\" dan \"Pertahanan Dasar\" sebesar 0.03 poin, dan efek \"Seni yang Hilang\" menerima tambahan tingkat kritis dan kerusakan kritis sebesar 0.15%."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Inspirasi Kematian"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "· Setiap 1 poin tingkat isi ulang Aliemus yang dimiliki Boneka meningkatkan efek pemulihan hidup dari \"Operasi Luar\" dan \"Timbal Balik\" sebesar 0.5%."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Dekonstruksi Gnosis"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "· Setiap 1% properti penurunan segil hitam yang dimiliki oleh Ogier meningkatkan kekuatan sementara yang diterima oleh \"Tujuh Seni dan Kebajikan\" sebesar 3%."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Transmutasi tanpa bentuk"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "· Setiap 1% ketahanan terhadap kematian yang dimiliki oleh Alva meningkatkan kerusakan dasar yang dihasilkan sebesar 0.5%."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "Penglihatan dinamis"
  },
