  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "· Pembangkit Jenkin, roda takdir, dan perjanjian masing-masing memberikan peningkatan 1% Crit. Rate, meningkatkan kerusakan dasar \"Pukulan Dasar\" dan \"Cokelat Mobilisasi\" sebesar 2%."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Bersatu Melawan Musuh"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "· Setiap 1 poin tingkat isi ulang kunci perak yang disediakan oleh bangunan Erica sendiri, roda takdir, dan perjanjian, meningkatkan \"Peledakan Elektromagnetik\" membuat Erica mendapatkan Crit. Rate sementara dan Crit. DMG sebesar 0.5%."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Sumber Energi Eksternal"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "· Saat awal giliran, dapatkan 1 lapisan Mimpi Pengantar.\n· Setiap lapisan yang dihabiskan dari Mimpi Pengantar meningkatkan efek counter yang diterima oleh \"Pelindung Pengembara\" dan \"Kota Mimpi Mati\" dalam pertempuran ini sebesar 5%.\n· Setiap 1% properti kekuatan kerusakan yang disediakan oleh bangunan Wanda sendiri, roda takdir, dan perjanjian, meningkatkan efek counter yang diterima oleh \"Kota Mimpi Mati\" sebesar 0.75%."
  },
  AwakerTalent_55202_TalentName_1 = {Text = "Revelasi"},
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "· Setiap 1 poin penguasaan Alam perjanjian yang disediakan oleh bangunan Casiah sendiri, roda takdir, dan perjanjian, \"Karnaval Ajaib\" meningkatkan semua kerusakan dasar Casiah sebesar 0.2%."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Maestro Sihir"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "· Setiap 1% properti penurunan segil hitam yang disediakan oleh bangunan Tinct sendiri, roda takdir, dan perjanjian, meningkatkan \"Cahaya Bintang\" mendapatkan 0.15% Crit. Rate sementara."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Perjalanan Planet"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·Pukulan Dasar dan Pertahanan Dasar Horla juga dianggap sebagai sebuah puisi. Saat Lompatan puisi, akan beralih ke emosi yang berbeda, yang dapat mempengaruhi efek puisi ini secara langsung. Berada dalam emosi yang berbeda akan memberikan efek berkelanjutan yang berbeda pada tim. \n·Setiap 1% Ketahanan yang dimiliki Horla, akan meningkatkan bonus efek ini sebesar 0.1% dari nilai awal."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Pena menciptakan perasaan"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·Faros setiap memiliki 1% atribut Kerusakan Kuat, perisai yang dihasilkan oleh \"Kota yang Hilang\" akan meningkat sebesar 0,4%."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Kecanduan Pulang Kampung"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "· Setiap 1% properti penurunan segil hitam yang dimiliki Caecus memberikan peningkatan 1% pada \"Pukulan Dasar\" dengan tambahan counter."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Duri Pemberontak"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "· Setelah Celeste memainkan kartu perintah, aktifkan 1 serangan tentakel terhadap musuh, setiap 1 poin penguasaan Alam yang dimiliki oleh Celeste sendiri, roda takdir, dan perjanjian akan menghasilkan 0.5% kerusakan tentakel dari aktivasi ini."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Sudut Penjelajahan Jauh"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "· Untuk setiap 1% kekayaan segel hitam yang dimiliki Salvador, batas maksimum dapur merah meningkat sebesar 0.15% kesehatan maksimum."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "Asal mula hidup"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "· Untuk setiap peningkatan 1% kekayaan segel hitam milik Agrippa, roda takdir, dan perjanjian meningkatkan perisai dasar \"Perlindungan Pucat\" sebesar 0.5% dan meningkatkan racun dasar sebesar 1%."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Tanda Perjanjian"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "· Setiap 1% properti ketahanan terhadap kematian yang dimiliki oleh Faint meningkatkan peningkatan counter yang diterima oleh \"Buaian Para Bintang\" dan \"Warna yang menyilaukan\" sebesar 0.2%, dan batas ketahanan terhadap kematian dari \"Buaian Para Bintang\" meningkat sebesar 2%."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Cradle Sekunder"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "· Setiap 1% properti kekuatan kerusakan yang dimiliki oleh Helot meningkatkan kerusakan yang ditimbulkan oleh Helot selama giliran ini sebesar 0.3%."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Cicatriz Kesakitan"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·Ryker mendapatkan 5 Segil hitam setiap kali membunuh musuh, setiap 1% penurunan Segil hitam akan meningkatkan jumlah yang diperoleh sebesar 1%, berlaku maksimal 5 kali setiap eksplorasi. \n·Mendapatkan 50/125/250 Segil hitam melalui pertempuran, Batas Relik +1, saat pertempuran berakhir, pilih satu <C05_zaowu:「Warisan Kekacauan」> untuk ditambahkan ke daftar Relik."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Pemenang mengambil semuanya"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "· Dalam pertempuran bos, pada awal giliran dan setelah \"Meleburkan Boneka\" melepaskan Aliemus, dapatkan 1 lapisan \"Akhir\". \"Akhir\" paling banyak memiliki 10 lapisan, ketika mencapai 10 lapisan, masukkan 1 kartu \"Penghancuran Ilusi\" ke dalam tangan."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Jalur Pemusnahan"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Rouse, ia akan memperoleh [Arg2] Keyflare.\n· Setiap serangan tentakel akan meningkatkan Kerusakan sementara tentakel sebesar [Arg3]% dari serangan Tulu, dan dapat berlaku maksimal [Arg4] kali per putaran.\n· Ketika terdapat 1/2/3 Pembangun \"Lemuria\" lain dalam tim, kerusakan tentakel yang diterima semua musuh meningkat 10%/25%/50%."
  },
