  AwakerTalent_74105_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Rouse, ia akan memperoleh [Arg2] Keyflare.\n· Setiap kali \"Samudera yang Ramai\" menghabiskan 1 lembar \"Pembagian kelenjar\", Aurita meningkatkan kerusakan yang ditimbulkan dalam pertarungan ini sebesar [Arg3]% ATK. Dalam Pertarungan Pemimpin, jika \"Samudera yang Ramai\" telah menghabiskan setidaknya 20 lembar \"Pembagian kelenjar\", jumlah serangan yang ditimbulkan oleh \"Pembagian kelenjar\" dan saat dikonsumsi bertambah 1. [Arg4] kartu \"Pembagian kelenjar\" pertama yang dimainkan setiap giliran tidak akan menambahkan \"Harmonisasi Daya Komputasi\"."
