  AwakerTalent_74109_TalentDesc_1 = {
    Text = "· Kemampuan ini hanya berlaku dalam level \"Astro Tale\".\n· Fisik, serangan, dan pertahanan pembangunan ini meningkat [Arg1] %, dan memperoleh [Arg2] poin energi-s kunci perak setelah pertama kali menggunakan kebangkitan gnosis.\n· 10 kartu pertama \"Cokelat Mobilisasi\" yang dimainkan setiap putaran tidak akan menambahkan \"Harmoni Aritmetika\".\n· Kerusakan yang disebabkan oleh Jenkin meningkat sebanding dengan [Arg3]% dari kekuatan serangan."
  },
