  AwakerTalent_74110_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n· Setelah memainkan \"Inspirasi\", memperoleh Kekuatan sementara sebesar [Arg3]% dari serangan, dan memicu 1 kali \"Nada Bertenaga\", maksimal berlaku 5 kali per giliran."
