    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n· Saat pertarungan dimulai, jika terdapat musuh \"Binatang Buas\", Kekuatan yang dihasilkan Cassia dalam pertarungan ini meningkat [Arg3]%. Setelah \"Lenyap Semua\" digunakan pertama kali setiap giliran, memicu efek Gelombang Sisa dari kartu yang dikocok ke tumpukan undian."
