  AwakerTalent_74113_TalentDesc_1 = {
    Text = "·Talent ini hanya berlaku di level \"Bab Bintang\".\n·CON, ATK, dan Pertahanan Awakener ini meningkat sebesar [Arg1]%, dan setelah pertama kali play Rouse, Awakener ini mendapatkan [Arg2] poin Keyflare.\n·\"Whip of Aliemus\" mendapatkan Retain dan Prepare. Musuh yang berniat menyebabkan kerusakan menerima Active DMG Pandia meningkat [Arg3]%, setiap serangan tambahan target meningkatkan 5%, maksimal meningkat tambahan 20%."
  },
