    Text = "· Talenta ini hanya berlaku di level\"Star Chapter\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1]%, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, mereka akan memperoleh [Arg2] Energi-s Kunci perak. \n· [Arg3] kartu pertama dari \"Teriaklah, Darah\" yang dimainkan setiap ronde tidak akan menambahkan \"Aritmetika Harmonisasi\". Kerusakan dasar yang diberikan oleh Uvhash meningkat sebesar [Arg4]%, dan efeknya menjadi dua kali lipat saat hidup di bawah 25%."
