  AwakerTalent_74116_TalentDesc_1 = {
    Text = "·Talenta ini hanya berlaku dalam tahap \"Bab Bintang\".\n·Fisik, Serangan, dan Pertahanan Pembangun ini meningkat sebesar [Arg1]% dan Pembangun ini akan mendapatkan [Arg2] poin Energi-s Kunci Perak setelah pertama kali melakukan Membangkitkan Gnosis.\n·Ketika Thais \"Melahap\" embrio, Thais memperoleh [Arg3]% Energi isi ulang Kunci Perak, dan Efek pemakanan \"Anak Suci\" digandakan."
  },
