  AwakerTalent_74118_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n· Kerusakan dasar yang dihasilkan oleh Goliath meningkat sebesar [Arg3]%,\"Kekuatan Bilah Raksasa\" meningkatkan sementara kerusakan akhir yang dihasilkan oleh Goliath sebesar [Arg4]%.\n· Ketika terdapat 1/2/3 Pembangun \"Lemuria\" lain dalam tim, efek perolehan kekuatan semua Pembangun meningkat tambahan sebesar 6%/15%/30%."
  },
