  AwakerTalent_74120_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Awakener ini meningkat sebesar [Arg1] %, dan setelah Awakener ini pertama kali mencapai Rouse, ia akan memperoleh [Arg2] Keyflare.\n· Kerusakan Dasar yang disebabkan oleh kartu perintah Lotan meningkat sebesar [Arg3] %. Setiap kali Lotan menyebabkan 1 kerusakan, kerusakan akhir yang dihasilkan oleh Lotan dalam giliran ini meningkat sebesar 5%, maksimum hingga [Arg4] %."
  },
