  AwakerTalent_74124_TalentDesc_1 = {
    Text = "·Talenta ini hanya berfungsi di level \"Bagian Bintang\".\n·Kekuatan fisik, serangan, dan pertahanan dari Pembangun ini meningkat sebesar [Arg1] %, dan Pembangun ini memperoleh [Arg2] poin Energi-s setelah melakukan Bangun Gnosis untuk pertama kalinya.\n·Aliemus yang dihasilkan oleh Boneka dan efek pengobatan yang dihasilkan oleh Muliakan meningkat sebesar [Arg3]%, dan setiap ada 1 Pembangun lain dari alam \"Kekacauan\" dalam tim, efek ini meningkat tambahan [Arg4]%."
  },
