  AwakerTalent_74126_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n· Efek perolehan Kekuatan Rhea meningkat [Arg4]%, setelah memainkan \"Kartu Perintah\" Rhea, memperoleh Kekuatan sebesar [Arg3]% dari serangan Rhea, efek ini meningkat hingga 200% berdasarkan HP yang hilang saat ini, maksimal aktif 3 kali per giliran."
