  AwakerTalent_74129_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n· Kerusakan akhir \"Serangan\" Lily meningkat [Arg3]%, peningkatan berlipat ganda di pertarungan Bos. Setelah menerima serangan dari musuh \"Superdimensi\", memperoleh efek pemulihan tertunda sebesar [Arg4]% dari HP yang hilang akibat serangan tersebut.\"Serangan Balasan\" menikmati bonus penguatan kerusakan [Arg5]% pada efek peningkatan kerusakan dari \"Kesabaran\"."
