  AwakerTalent_74132_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Rouse, ia akan memperoleh [Arg2] Energi-s.\n· Racun yang disebabkan oleh Faros meningkat sebesar [Arg3] %. Pada akhir putaran \"Lemuria, Kota yang Hilang\", perintahkan semua Tentacle untuk menyerang 1 kali, tetapi serangan ini hanya menyebabkan [Arg4]% kerusakan.\n· Ketika terdapat 1/2/3 Pembangun \"Lemuria\" lainnya dalam tim, Penguatan Kerusakan +20%/50%/100%."
