  AwakerTalent_74134_TalentDesc_1 = {
    Text = "·Keahlian ini hanya berlaku di level \"Cahaya Bintang\".\n·Kondisi dan serangan Pembangun ini meningkat [Arg1] %, dan Pembangun ini yang pertama kali menggunakan Membangkitkan Gnosis setelahnya mendapatkan [Arg2] poin Energi-s.\n·Helot meningkatkan kerusakan akhir yang diberikan ke musuh \"Salju\" sebesar [Arg3]%. Jika pada giliran ini Helot mengonsumsi \"Embrio\", pada kerusakan berikutnya yang dihasilkan pada giliran ini, kerusakan kritis +[Arg4]%."
  },
