    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n· Saat pertarungan bos dimulai, memperoleh Resistansi Kematian setara dengan [Arg3]% atribut Resistansi Kematian Orla. Setiap kali Resistansi Kematian terpicu, efek terkait \"Bab Kemegahan\" meningkat [Arg4]% hingga akhir giliran."
