  AwakerTalent_74137_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Rouse, ia akan memperoleh [Arg2] Keyflare.\n· Ketika \"Reruntuhan Abu\" disegarkan, kemungkinan munculnya diskon meningkat sebesar [Arg3] %, dan proporsi diskon meningkat sebesar [Arg4] %.\n·\"Serangan Pematah Leher\" meningkatkan kerusakan dasar sebesar [Arg5] %, dihitung secara terpisah dari peningkatan kerusakan dasar yang diperoleh dari pembunuhan."
  },
