  AwakerTalent_74140_TalentDesc_1 = {
    Text = "·Talenta ini hanya berlaku di level \"Bagian Bintang\".\n·Kondisi tubuh, serangan, dan pertahanan Pembangun ini meningkat [Arg1] %, dan membuat Pembangun ini mendapatkan [Arg2] poin Energi Kunci perak setelah pertama kali menggunakan Membangkitkan Gnosis.\n·Setiap kali mendapatkan Pengorbanan, juga akan mendapatkan kerusakan Tentakel yang setara dengan [Arg3]% dari jumlah Pengorbanan."
