  AwakerTalent_78618_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n·\"Penebusan Penderitaan\" meningkatkan efek kerusakan dasar yang diberikan sebesar [Arg3]% dari kekuatan serangan Pollux.\n· Setiap menumpuk 50 lapis \"Segel Dosa\", 1 kartu \"Hati Suci\" ditempatkan ke tangan.\n·Setelah \"Segel Dosa\" mencapai 100 lapis,\"Hati Suci\" setelah dikonsumsi karena dimainkan ke-3 kalinya akan menarik 1 \"Kartu Skill\" milik sendiri.\n· Saat memberikan kerusakan, efek \"Segel Dosa\" terhadap musuh \"Gereja Lentera\" berlipat ganda."
  },
