  AwakerTalent_78620_TalentDesc_1 = {
    Text = "·Talent ini hanya berlaku di level \"Bab Bintang\".\n·CON, ATK, dan Pertahanan Awakener ini meningkat sebesar [Arg1]%, dan setelah pertama kali play Rouse, Awakener ini mendapatkan [Arg2] poin Keyflare.\n·Saat pertempuran dimulai, Kerusakan tentakel yang diterima semua musuh meningkat [Arg3]%, efeknya berlipat ganda terhadap musuh \"Aequor\". Active DMG yang diberikan \"Hukuman Petir\" kepada musuh \"Aequor\" meningkat [Arg4]%."
  },
