    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi-s.\n·\"Nyata, Juga Fantasi\" tambahan meningkatkan kerusakan akhir yang disebabkan oleh Ledakan Kegilaan Pembangun lain pada giliran ini sebesar [Arg3]%, setelah digunakan, Kegilaan dasar Pickman berkurang 5 poin."
