  AwakerTalent_78642_TalentDesc_1 = {
    Text = "·Talenta ini hanya berlaku di tingkat \"Bab Bintang\".\n·Konstitusi, serangan, dan pertahanan Awakener ini meningkat sebesar [Arg1] %, dan Awakener ini mendapatkan [Arg2] poin Keyflare setelah pertama kali melakukan Gnosis Awaken. \n·\"Putusan Takdir\" yang dihasilkan oleh Arachne meningkat sebesar [Arg3]%, dan \"Putusan Takdir\" yang mengenai musuh Mutan menjadi dua kali lipat."
