  AwakerTalent_78645_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1]%, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Keyflare.\n· Semua Pembangun mendapatkan peningkatan Kekuatan sebesar [Arg3]%.\n· Clementine memberikan Kerusakan kepada musuh \"Insectoid\" dan menerapkan efek Bleed sebesar [Arg4]% dari Kerusakan pada target. Setiap kali Clementine pertama kali memberikan Perisai atau HP Recovery di setiap giliran, musuh \"Insectoid\" sementara kehilangan pertahanan sebesar [Arg5]% dari Kekuatan."
  },
  AwakerTalent_78645_TalentDesc_10 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1]%, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Keyflare.\n· Semua Pembangun mendapatkan peningkatan Kekuatan sebesar [Arg3]%.\n· Clementine memberikan Kerusakan kepada musuh \"Insectoid\" dan menerapkan efek Bleed sebesar [Arg4]% dari Kerusakan pada target. Setiap kali Clementine pertama kali memberikan Perisai atau HP Recovery di setiap giliran, musuh \"Insectoid\" sementara kehilangan pertahanan sebesar [Arg5]% dari Kekuatan."
  },
