  AwakerTalent_78911_TalentDesc_1 = {
    Text = "· Talenta ini hanya berlaku di level \"Bab Bintang\".\n· Konstitusi, serangan, dan pertahanan Pembangun ini meningkat sebesar [Arg1] %, dan setelah Pembangun ini pertama kali mencapai Membangkitkan Gnosis, ia akan memperoleh [Arg2] Energi Kunci Perak.\n· Kerusakan yang disebabkan oleh Delusi·Murphy menambahkan [Arg3]%\"Pengorbanan\", efek peningkatan \"Kontrak Takdir\" terhadap \"Ritual Kelahiran\" berlipat ganda.\n· Saat terdapat 1/2/3 Pembangun \"Lemuria\" lain dalam tim, batas HP meningkat 6%/15%/30%. Setelah Pembangun \"Lemuria\" melepaskan Ledakan Kegilaan, memperoleh perisai sebesar 50%/125%/250% pertahanan Delusi·Murphy, efek ini berlaku maksimal 1 kali per giliran dan tidak terpengaruh oleh efek peningkatan perisai."
  },
