  AwakerTalent_79211_TalentDesc_1 = {
    Text = "· Kartu perintah Klemantin menghasilkan kerusakan setelah memperoleh 1 lapisan 'Empati'.\n· Pembangun Klemantin sendiri, Roda takdir, dan Perjanjian masing-masing memberikan 1 poin atribut isi ulang kunci perak, meningkatkan tingkat kritis dan kerusakan kritis sebesar 0.35%.\n· Setelah awal giliran Ultra, hapus semua 'Trauma Roh' dan 'Kecemasan' musuh. Setiap menghapus 1 lapisan 'Trauma Roh' dari semua musuh akan mendapatkan 50 poin Energi-s kunci perak, setiap lapisan 'Kecemasan' yang dihapus dari semua musuh akan memberikan 2 poin Kegilaan kepada Pembangun lainnya."
  },
