  AwakerTalent_89775_TalentDesc_1 = {
    Text = "·Setiap kali memainkan \"Helaian Bulu Onyx\" pertama dalam satu ronde, terapkan \"Korosi\" sebesar 840% dari kekuatan serangan sendiri kepada semua musuh dan dapatkan 10 poin Aliemus. \n·Setiap 1% Amplifikasi Kerusakan yang dimiliki Castor meningkatkan \"Korosi\" dasar yang diterapkan sebesar 1%. \n·Setelah pertempuran berakhir,\"Korosi\" yang diterapkan oleh Castor dalam eksplorasi ini meningkat permanen sebesar 20%. \n·\"Korosi\" yang diterapkan dalam Pertarungan Pemimpin meningkat dua kali lipat. \n·Setelah Castor menerapkan \"Korosi\", kerusakan yang dihasilkan olehnya dalam ronde ini meningkat sebesar 5% dari jumlah yang diterapkan. \n·Kerusakan yang dihasilkan oleh Castor tidak akan menghapus \"Korosi\"."
  },
  AwakerTalent_89775_TalentName_1 = {
